window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-0c3d3227a0ac6869"]={"versions": [{"id": "FIG-0c3d3227a0ac6869", "releases": ["R3.0.7"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Metamodell-Struktur des AUTOSAR-System-Templates. Dargestellt ist die strukturelle Verankerung der obersten Software-Komposition (<code>SoftwareComposition</code>) und des System-Mappings (<code>SystemMapping</code>) innerhalb des Wurzelelements <code>System</code> sowie die Anbindung von FIBEX-Kommunikationsartefakten (<code>FibexCore::FibexElement</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Klassendiagramm spezifiziert folgende Entitäten, Attribute und Assoziationen:</p>\n<ul class=\"fig-list\">\n<li><code>System</code>: Zentrales Top-Level-Element, spezialisiert <code>ARElement</code> und trägt das Stereotyp <code>«atpStructureElement»</code>. Attribute:</li>\n<li><code>ecuExtractVersion: String [0..1]</code></li>\n<li><code>systemVersion: String</code></li>\n<li><code>SoftwareComposition</code>: Spezialisiert <code>Identifiable</code>, stereotypisiert als <code>«atpPrototype»</code>. Wird von <code>System</code> per Komposition aggregiert (<code>+softwareComposition 1</code>).</li>\n<li><code>CompositionType</code>: Aus Paket <code>Composition</code>, spezialisiert <code>ComponentType</code>, stereotypisiert als <code>«atpType»</code>. Steht über die typisierende Assoziation <code>«isOfType»</code> in Beziehung zu <code>SoftwareComposition</code> (<code>+softwareComposition 1</code> am Typende, Multiplizität <code>*</code> am Prototypende).</li>\n<li><code>SystemMapping</code>: Spezialisiert <code>Identifiable</code>. Wird von <code>System</code> per Komposition aggregiert (<code>+mapping 1</code>).</li>\n<li><code>FibexCore::FibexElement</code>: Spezialisiert <code>PackageableElement</code>. Wird von <code>System</code> über eine gerichtete Assoziation referenziert (<code>+fibexElement *</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Verhaltens- oder Sequenzdiagramm-Elemente. Die Beziehungen definieren die statische Strukturhierarchie zur Systemgenerierung und Software-Zusammenstellung.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Ein AUTOSAR-System verlangt zwingend genau eine Top-Level-Softwarekomposition (<code>softwareComposition 1</code>) sowie genau ein System-Mapping (<code>mapping 1</code>), welches die Abbildung von Softwarekomponenten auf Steuergeräte vornimmt. Kommunikationsartefakte werden über beliebig viele FIBEX-Elemente eingebunden. Die Systemversion ist obligatorisch anzugeben, während die Version des ECU-Extrakts optional ist.</p>"}, {"id": "FIG-8b7486956206a43a", "releases": ["R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Metamodell-Struktur des AUTOSAR-System-Templates. Dargestellt ist die strukturelle Verankerung der obersten Software-Komposition (<code>SoftwareComposition</code>) und des System-Mappings (<code>SystemMapping</code>) innerhalb des Wurzelelements <code>System</code> sowie die Anbindung von FIBEX-Kommunikationsartefakten (<code>FibexCore::FibexElement</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Klassendiagramm spezifiziert folgende Entitäten, Attribute und Assoziationen:</p>\n<ul class=\"fig-list\">\n<li><code>System</code>: Zentrales Top-Level-Element, spezialisiert <code>ARElement</code> und trägt das Stereotyp <code>«atpStructureElement»</code>. Attribute:</li>\n<li><code>ecuExtractVersion: String [0..1]</code></li>\n<li><code>systemVersion: String</code></li>\n<li><code>SoftwareComposition</code>: Spezialisiert <code>Identifiable</code>, stereotypisiert als <code>«atpPrototype»</code>. Wird von <code>System</code> per Komposition aggregiert (<code>+softwareComposition 1</code>).</li>\n<li><code>CompositionType</code>: Aus Paket <code>Composition</code>, spezialisiert <code>ComponentType</code>, stereotypisiert als <code>«atpType»</code>. Steht über die typisierende Assoziation <code>«isOfType»</code> in Beziehung zu <code>SoftwareComposition</code> (<code>+softwareComposition 1</code> am Typende, Multiplizität <code>*</code> am Prototypende).</li>\n<li><code>SystemMapping</code>: Spezialisiert <code>Identifiable</code>. Wird von <code>System</code> per Komposition aggregiert (<code>+mapping 1</code>).</li>\n<li><code>FibexCore::FibexElement</code>: Spezialisiert <code>PackageableElement</code>. Wird von <code>System</code> über eine gerichtete Assoziation referenziert (<code>+fibexElement *</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Verhaltens- oder Sequenzdiagramm-Elemente. Die Beziehungen definieren die statische Strukturhierarchie zur Systemgenerierung und Software-Zusammenstellung.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Ein AUTOSAR-System verlangt zwingend genau eine Top-Level-Softwarekomposition (<code>softwareComposition 1</code>) sowie genau ein System-Mapping (<code>mapping 1</code>), welches die Abbildung von Softwarekomponenten auf Steuergeräte vornimmt. Kommunikationsartefakte werden über beliebig viele FIBEX-Elemente eingebunden. Die Systemversion ist obligatorisch anzugeben, während die Version des ECU-Extrakts optional ist.</p>"}, {"id": "FIG-fbdcd4249609ea38", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Metamodell-Struktur des AUTOSAR-System-Templates. Dargestellt ist die strukturelle Verankerung der obersten Software-Komposition (<code>SoftwareComposition</code>) und des System-Mappings (<code>SystemMapping</code>) innerhalb des Wurzelelements <code>System</code> sowie die Anbindung von FIBEX-Kommunikationsartefakten (<code>FibexCore::FibexElement</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Klassendiagramm spezifiziert folgende Entitäten, Attribute und Assoziationen:</p>\n<ul class=\"fig-list\">\n<li><code>System</code>: Zentrales Top-Level-Element, spezialisiert <code>ARElement</code> und trägt das Stereotyp <code>«atpStructureElement»</code>. Attribute:</li>\n<li><code>ecuExtractVersion: String [0..1]</code></li>\n<li><code>pncVectorLength: Integer [0..1]</code></li>\n<li><code>pncVectorOffset: Integer [0..1]</code></li>\n<li><code>systemVersion: String</code></li>\n<li><code>SoftwareComposition</code>: Spezialisiert <code>Identifiable</code>, stereotypisiert als <code>«atpPrototype»</code>. Wird von <code>System</code> per Komposition aggregiert (<code>+softwareComposition 0..1</code>).</li>\n<li><code>CompositionType</code>: Aus Paket <code>Composition</code>, spezialisiert <code>ComponentType</code>, stereotypisiert als <code>«atpType»</code>. Steht über die typisierende Assoziation <code>«isOfType»</code> in Beziehung zu <code>SoftwareComposition</code> (<code>+softwareComposition 1</code> am Typende, Multiplizität <code>*</code> am Prototypende).</li>\n<li><code>SystemMapping</code>: Spezialisiert <code>Identifiable</code>. Wird von <code>System</code> per Komposition aggregiert (<code>+mapping 0..1</code>).</li>\n<li><code>FibexCore::FibexElement</code>: Spezialisiert <code>PackageableElement</code>. Wird von <code>System</code> über eine gerichtete Assoziation referenziert (<code>+fibexElement *</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Verhaltens- oder Sequenzdiagramm-Elemente. Die Beziehungen definieren die statische Strukturhierarchie zur Systemgenerierung und Software-Zusammenstellung.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Sowohl die Top-Level-Softwarekomposition (<code>softwareComposition 0..1</code>) als auch das System-Mapping (<code>mapping 0..1</code>) sind optional. Für partielle Systembeschreibungen kann ein System somit ohne Softwarekomposition oder Mapping existieren. Die neuen optionalen Attribute <code>pncVectorLength</code> und <code>pncVectorOffset</code> dienen der Konfiguration des Partial Networking Cluster Vektors. Die Systemversion bleibt verpflichtend.</p>"}, {"id": "FIG-a65899894acfeb62", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Metamodell-Struktur des AUTOSAR-System-Templates (AUTOSAR 4). Dargestellt ist die Integration der Root-Software-Komposition (<code>RootSwCompositionPrototype</code>) in das Element <code>System</code>, flankiert von <code>FlatMap</code>, variablen <code>SystemMapping</code>-Definitionen, <code>FibexElement</code>-Referenzen und AUTOSAR-Variabilitätsmechanismen (<code>«atpVariation»</code>, <code>«atpSplitable»</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Klassendiagramm spezifiziert folgende Entitäten, Attribute und Assoziationen:</p>\n<ul class=\"fig-list\">\n<li><code>System</code>: Spezialisiert <code>ARElement</code> und <code>AtpStructureElement</code>. Attribute:</li>\n<li><code>ecuExtractVersion: RevisionLabelString [0..1]</code></li>\n<li><code>pncVectorLength: PositiveInteger [0..1]</code></li>\n<li><code>pncVectorOffset: PositiveInteger [0..1]</code></li>\n<li><code>systemVersion: RevisionLabelString</code></li>\n<li><code>RootSwCompositionPrototype</code>: Spezialisiert <code>AtpPrototype</code> und <code>Identifiable</code>. Wird von <code>System</code> aggregiert (<code>+rootSoftwareComposition 0..1</code>, annotiert mit <code>«atpVariation»</code> und Tag <code>Vh.latestBindingTime = SystemDesignTime</code>).</li>\n<li><code>CompositionSwComponentType</code>: Paket <code>Composition</code>, spezialisiert <code>SwComponentType</code>. Ist über Assoziation <code>«isOfType»</code> mit <code>RootSwCompositionPrototype</code> verbunden (<code>+softwareComposition 1 {redefines atpType}</code>, Gegenseite <code>*</code>).</li>\n<li><code>FlatMap</code>: Paket <code>FlatMap</code>, spezialisiert <code>ARElement</code>, <code>AtpBlueprint</code> und <code>AtpBlueprintable</code>. Ist über Assoziation <code>+flatMap 0..1</code> von <code>RootSwCompositionPrototype</code> aus angebunden.</li>\n<li><code>SystemMapping</code>: Spezialisiert <code>Identifiable</code>. Wird von <code>System</code> aggregiert (<code>+mapping 0..*</code>, annotiert mit <code>«atpVariation,atpSplitable»</code> und Tag <code>Vh.latestBindingTime = PostBuild</code>).</li>\n<li><code>FibexCore::FibexElement</code>: Spezialisiert <code>PackageableElement</code>. Wird von <code>System</code> referenziert (<code>+fibexElement *</code>, annotiert mit <code>«atpVariation»</code> und Tag <code>Vh.latestBindingTime = PostBuild</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Verhaltens- oder Sequenzdiagramm-Elemente. Die Beziehungen definieren die statische Strukturhierarchie zur Systemgenerierung und Software-Zusammenstellung.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Metamodellierung nutzt typisierte AUTOSAR-Basisdatentypen (<code>RevisionLabelString</code>, <code>PositiveInteger</code>). Die Root-Softwarekomposition ist ein variabler Prototyp mit der spätesten Bindungszeit <code>SystemDesignTime</code>. System-Mappings und FIBEX-Elemente unterstützen Post-Build-Variabilität; <code>SystemMapping</code> ist zusätzlich splitbar (<code>«atpSplitable»</code>), sodass Mapping-Definitionen über mehrere ARXML-Dateien fragmentiert werden können. Über <code>FlatMap</code> kann eine abgeflachte Darstellung der hierarchischen Software-Architektur referenziert werden.</p>"}, {"id": "FIG-47c6d78759dd8d22", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Metamodell-Struktur des AUTOSAR-System-Templates (AUTOSAR 4). Dargestellt ist die Integration der Root-Software-Komposition (<code>RootSwCompositionPrototype</code>) in das Element <code>System</code>, flankiert von <code>FlatMap</code>, variablen <code>SystemMapping</code>-Definitionen, <code>FibexElement</code>-Referenzen und AUTOSAR-Variabilitätsmechanismen (<code>«atpVariation»</code>, <code>«atpSplitable»</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Klassendiagramm spezifiziert folgende Entitäten, Attribute und Assoziationen:</p>\n<ul class=\"fig-list\">\n<li><code>System</code>: Spezialisiert <code>ARElement</code> und <code>AtpStructureElement</code>. Attribute:</li>\n<li><code>ecuExtractVersion: RevisionLabelString [0..1]</code></li>\n<li><code>pncVectorLength: PositiveInteger [0..1]</code></li>\n<li><code>pncVectorOffset: PositiveInteger [0..1]</code></li>\n<li><code>systemVersion: RevisionLabelString</code></li>\n<li><code>RootSwCompositionPrototype</code>: Spezialisiert <code>AtpPrototype</code> und <code>Identifiable</code>. Wird von <code>System</code> aggregiert (<code>+rootSoftwareComposition 0..1</code>, annotiert mit <code>«atpVariation»</code> und Tag <code>vh.latestBindingTime = systemDesignTime</code>).</li>\n<li><code>CompositionSwComponentType</code>: Spezialisiert <code>SwComponentType</code>. Ist über Assoziation <code>«isOfType»</code> mit <code>RootSwCompositionPrototype</code> verbunden (<code>+softwareComposition 1 {redefines atpType}</code>, Gegenseite <code>*</code>).</li>\n<li><code>FlatMap</code>: Spezialisiert <code>ARElement</code>, <code>AtpBlueprint</code> und <code>AtpBlueprintable</code>. Ist über gerichtete Assoziation <code>+flatMap 0..1</code> mit Stereotyp <code>«atpSplitable»</code> von <code>RootSwCompositionPrototype</code> aus angebunden.</li>\n<li><code>SystemMapping</code>: Spezialisiert <code>Identifiable</code>. Wird von <code>System</code> aggregiert (<code>+mapping 0..*</code>, annotiert mit <code>«atpVariation,atpSplitable»</code> und Tag <code>vh.latestBindingTime = postBuild</code>).</li>\n<li><code>FibexElement</code>: Spezialisiert <code>PackageableElement</code>. Wird von <code>System</code> referenziert (<code>+fibexElement *</code>, annotiert mit <code>«atpVariation»</code> und Tag <code>vh.latestBindingTime = postBuild</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Verhaltens- oder Sequenzdiagramm-Elemente. Die Beziehungen definieren die statische Strukturhierarchie zur Systemgenerierung und Software-Zusammenstellung.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Referenz von <code>RootSwCompositionPrototype</code> auf <code>FlatMap</code> ist als <code>«atpSplitable»</code> gekennzeichnet, womit die Zuordnung der FlatMap über verschiedene Datei-Teilmengen hinweg aufgeteilt werden darf. Tag-Namen und Werte für Bindungszeiten folgen der camelCase-Konvention (<code>systemDesignTime</code>, <code>postBuild</code>).</p>"}, {"id": "FIG-b4e7ad31f601609c", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Metamodell-Struktur des AUTOSAR-System-Templates. Dargestellt ist die Integration der Root-Software-Komposition in <code>System</code>, ergänzt um FlatMap, variable System-Mappings, FibexElement-Referenzen sowie Mechanismen zur Definition von Client-IDs (<code>ClientIdDefinitionSet</code>, <code>ClientIdDefinition</code>) und deren Verknüpfung mit Client-Server-Operationen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Klassendiagramm spezifiziert folgende Entitäten, Attribute und Assoziationen:</p>\n<ul class=\"fig-list\">\n<li><code>System</code>: Spezialisiert <code>ARElement</code> und <code>AtpStructureElement</code>. Attribute:</li>\n<li><code>containerIPduHeaderByteOrder: ByteOrderEnum [0..1]</code></li>\n<li><code>ecuExtractVersion: RevisionLabelString [0..1]</code></li>\n<li><code>pncVectorLength: PositiveInteger [0..1]</code></li>\n<li><code>pncVectorOffset: PositiveInteger [0..1]</code></li>\n<li><code>systemVersion: RevisionLabelString</code></li>\n<li><code>RootSwCompositionPrototype</code>: Spezialisiert <code>AtpPrototype</code> und <code>Identifiable</code>. Wird von <code>System</code> aggregiert (<code>+rootSoftwareComposition 0..1</code>, annotiert mit <code>«atpVariation,atpSplitable»</code> und Tag <code>vh.latestBindingTime = systemDesignTime</code>).</li>\n<li><code>CompositionSwComponentType</code>: Spezialisiert <code>SwComponentType</code>. Assoziiert mit <code>RootSwCompositionPrototype</code> über <code>«isOfType»</code> (<code>+softwareComposition 1 {redefines atpType}</code>, Gegenseite <code>*</code>).</li>\n<li><code>FlatMap</code>: Spezialisiert <code>ARElement</code>, <code>AtpBlueprint</code>, <code>AtpBlueprintable</code>. Verbunden mit <code>RootSwCompositionPrototype</code> über Assoziation <code>+flatMap 0..1</code> (<code>«atpSplitable»</code>).</li>\n<li><code>SystemMapping</code>: Spezialisiert <code>Identifiable</code>. Aggregiert von <code>System</code> (<code>+mapping 0..*</code>, <code>«atpVariation,atpSplitable»</code>, Tag <code>vh.latestBindingTime = postBuild</code>).</li>\n<li><code>FibexElement</code>: Spezialisiert <code>PackageableElement</code>. Referenziert von <code>System</code> (<code>+fibexElement *</code>, <code>«atpVariation»</code>, Tag <code>vh.latestBindingTime = postBuild</code>).</li>\n<li><code>ClientIdDefinitionSet</code>: Spezialisiert <code>ARElement</code>. Wird von <code>System</code> aggregiert (<code>+clientIdDefinitionSet 0..*</code>).</li>\n<li><code>ClientIdDefinition</code>: Spezialisiert <code>Identifiable</code>, Attribut <code>clientId: Numerical</code>. Wird von <code>ClientIdDefinitionSet</code> aggregiert (<code>+clientIdDefinition 0..*</code>, <code>«atpVariation,atpSplitable»</code>).</li>\n<li><code>ClientServerOperation</code>: Spezialisiert <code>AtpStructureElement</code> und <code>Identifiable</code>. Wird von <code>ClientIdDefinition</code> per Instanz-Referenz adressiert (<code>+clientServerOperation «instanceRef»</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Verhaltens- oder Sequenzdiagramm-Elemente. Die Beziehungen definieren die statische Strukturhierarchie zur Systemgenerierung und Software-Zusammenstellung.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Byte-Reihenfolge von Container-I-PDU-Headern kann auf Systemebene über <code>containerIPduHeaderByteOrder</code> konfiguriert werden. Die Aggregation von <code>RootSwCompositionPrototype</code> ist nun neben Variation auch splitbar (<code>«atpVariation,atpSplitable»</code>). Für Client-Server-Kommunikation können über <code>ClientIdDefinitionSet</code> eindeutige Client-IDs (<code>Numerical</code>) modelliert und über <code>«instanceRef»</code> direkt an konkrete <code>ClientServerOperation</code>-Instanzen gebunden werden.</p>"}, {"id": "FIG-189e6e57e744ad1c", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Metamodell-Struktur des AUTOSAR-System-Templates. Dargestellt ist die Integration der Root-Software-Komposition in <code>System</code>, ergänzt um FlatMap, variable System-Mappings, FibexElement-Referenzen, Client-ID-Definitionen sowie J1939-Shared-Address-Cluster.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Klassendiagramm spezifiziert folgende Entitäten, Attribute und Assoziationen:</p>\n<ul class=\"fig-list\">\n<li><code>System</code>: Spezialisiert <code>ARElement</code> und <code>AtpStructureElement</code>. Attribute:</li>\n<li><code>containerIPduHeaderByteOrder: ByteOrderEnum [0..1]</code></li>\n<li><code>ecuExtractVersion: RevisionLabelString [0..1]</code></li>\n<li><code>pncVectorLength: PositiveInteger [0..1]</code></li>\n<li><code>pncVectorOffset: PositiveInteger [0..1]</code></li>\n<li><code>systemVersion: RevisionLabelString</code></li>\n<li><code>RootSwCompositionPrototype</code>: Spezialisiert <code>AtpPrototype</code> und <code>Identifiable</code>. Aggregiert von <code>System</code> (<code>+rootSoftwareComposition 0..1</code>, <code>«atpVariation,atpSplitable»</code>).</li>\n<li><code>CompositionSwComponentType</code>: Spezialisiert <code>SwComponentType</code>. Typisiert <code>RootSwCompositionPrototype</code> über <code>«isOfType»</code> (<code>+softwareComposition 1 {redefines atpType}</code>, Gegenseite <code>*</code>).</li>\n<li><code>FlatMap</code>: Spezialisiert <code>ARElement</code>, <code>AtpBlueprint</code>, <code>AtpBlueprintable</code>. Angebunden an <code>RootSwCompositionPrototype</code> über <code>+flatMap 0..1</code> (<code>«atpSplitable»</code>).</li>\n<li><code>SystemMapping</code>: Spezialisiert <code>Identifiable</code>. Aggregiert von <code>System</code> (<code>+mapping 0..*</code>, <code>«atpVariation,atpSplitable»</code>).</li>\n<li><code>FibexElement</code>: Spezialisiert <code>PackageableElement</code>. Referenziert von <code>System</code> (<code>+fibexElement *</code>, <code>«atpVariation»</code>).</li>\n<li><code>ClientIdDefinitionSet</code>: Spezialisiert <code>ARElement</code>. Aggregiert von <code>System</code> (<code>+clientIdDefinitionSet 0..*</code>).</li>\n<li><code>ClientIdDefinition</code>: Spezialisiert <code>Identifiable</code>, Attribut <code>clientId: Numerical</code>. Aggregiert von <code>ClientIdDefinitionSet</code> (<code>+clientIdDefinition 0..*</code>, <code>«atpVariation,atpSplitable»</code>).</li>\n<li><code>ClientServerOperation</code>: Spezialisiert <code>AtpStructureElement</code> und <code>Identifiable</code>. Referenziert von <code>ClientIdDefinition</code> über gerichtete Instanz-Referenz (<code>+clientServerOperation 1</code>, annotiert mit Stereotyp <code>«instanceRef»</code>).</li>\n<li><code>J1939SharedAddressCluster</code>: Spezialisiert <code>Identifiable</code>. Wird von <code>System</code> aggregiert (<code>+j1939SharedAddressCluster 0..*</code>, <code>«atpVariation,atpSplitable»</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Verhaltens- oder Sequenzdiagramm-Elemente. Die Beziehungen definieren die statische Strukturhierarchie zur Systemgenerierung und Software-Zusammenstellung.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Unterstützung für J1939-Netzwerke durch variable und splitbare Aggregation von <code>J1939SharedAddressCluster</code> (<code>0..*</code>) direkt am <code>System</code>. Die Instanz-Referenz <code>+clientServerOperation</code> von <code>ClientIdDefinition</code> auf <code>ClientServerOperation</code> ist explizit mit der Multiplizität <code>1</code> versehen. Explizite Bindungszeit-Annotationen an den Variationspunkten im Diagramm sind entfallen.</p>"}, {"id": "FIG-ef04d044cbe0688d", "releases": ["R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Metamodell-Struktur des AUTOSAR-System-Templates. Dargestellt ist die Integration der Root-Software-Komposition in <code>System</code>, ergänzt um FlatMap, variable System-Mappings, FibexElement-Referenzen, Client-ID-Definitionen sowie J1939-Shared-Address-Cluster.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Klassendiagramm spezifiziert folgende Entitäten, Attribute und Assoziationen:</p>\n<ul class=\"fig-list\">\n<li><code>System</code>: Spezialisiert <code>ARElement</code> und <code>AtpStructureElement</code>. Attribute:</li>\n<li><code>containerIPduHeaderByteOrder: ByteOrderEnum [0..1]</code></li>\n<li><code>ecuExtractVersion: RevisionLabelString [0..1]</code></li>\n<li><code>pncVectorLength: PositiveInteger [0..1]</code></li>\n<li><code>pncVectorOffset: PositiveInteger [0..1]</code></li>\n<li><code>systemVersion: RevisionLabelString</code></li>\n<li><code>RootSwCompositionPrototype</code>: Spezialisiert <code>AtpPrototype</code> und <code>Identifiable</code>. Aggregiert von <code>System</code> (<code>+rootSoftwareComposition 0..1</code>, <code>«atpVariation,atpSplitable»</code>).</li>\n<li><code>CompositionSwComponentType</code>: Spezialisiert <code>SwComponentType</code>. Typisiert <code>RootSwCompositionPrototype</code> über <code>«isOfType»</code> (<code>+softwareComposition 1 {redefines atpType}</code>, Gegenseite <code>*</code>).</li>\n<li><code>FlatMap</code>: Spezialisiert <code>ARElement</code>, <code>AtpBlueprint</code>, <code>AtpBlueprintable</code>. Angebunden an <code>RootSwCompositionPrototype</code> über <code>+flatMap 0..1</code> (<code>«atpSplitable»</code>).</li>\n<li><code>SystemMapping</code>: Spezialisiert <code>Identifiable</code>. Aggregiert von <code>System</code> (<code>+mapping 0..*</code>, <code>«atpVariation,atpSplitable»</code>).</li>\n<li><code>FibexElement</code>: Spezialisiert <code>PackageableElement</code>. Referenziert von <code>System</code> (<code>+fibexElement *</code>, <code>«atpVariation»</code>).</li>\n<li><code>ClientIdDefinitionSet</code>: Spezialisiert <code>ARElement</code>. Aggregiert von <code>System</code> (<code>+clientIdDefinitionSet 0..*</code>).</li>\n<li><code>ClientIdDefinition</code>: Spezialisiert <code>Identifiable</code>, Attribut <code>clientId: Numerical</code>. Aggregiert von <code>ClientIdDefinitionSet</code> (<code>+clientIdDefinition 0..*</code>, <code>«atpVariation,atpSplitable»</code>).</li>\n<li><code>ClientServerOperation</code>: Spezialisiert <code>AtpStructureElement</code> und <code>Identifiable</code>. Referenziert von <code>ClientIdDefinition</code> über gerichtete Instanz-Referenz (<code>+clientServerOperation 1</code>, annotiert mit Stereotyp <code>«instanceRef»</code>).</li>\n<li><code>J1939SharedAddressCluster</code>: Spezialisiert <code>Identifiable</code>. Wird von <code>System</code> aggregiert (<code>+j1939SharedAddressCluster 0..*</code>, <code>«atpVariation,atpSplitable»</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Verhaltens- oder Sequenzdiagramm-Elemente. Die Beziehungen definieren die statische Strukturhierarchie zur Systemgenerierung und Software-Zusammenstellung.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Unterstützung für J1939-Netzwerke durch variable und splitbare Aggregation von <code>J1939SharedAddressCluster</code> (<code>0..*</code>) direkt am <code>System</code>. Die Instanz-Referenz <code>+clientServerOperation</code> von <code>ClientIdDefinition</code> auf <code>ClientServerOperation</code> ist explizit mit der Multiplizität <code>1</code> versehen. Explizite Bindungszeit-Annotationen an den Variationspunkten im Diagramm sind entfallen.</p>"}, {"id": "FIG-e77496564191b9f7", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Metamodell-Struktur des AUTOSAR-System-Templates. Dargestellt ist die Integration der Root-Software-Komposition in <code>System</code>, ergänzt um FlatMap, variable System-Mappings, FibexElement-Referenzen, Client-ID-Definitionen sowie J1939-Shared-Address-Cluster.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Klassendiagramm spezifiziert folgende Entitäten, Attribute und Assoziationen:</p>\n<ul class=\"fig-list\">\n<li><code>System</code>: Spezialisiert <code>ARElement</code> und <code>AtpStructureElement</code>. Attribute:</li>\n<li><code>containerIPduHeaderByteOrder: ByteOrderEnum [0..1]</code></li>\n<li><code>ecuExtractVersion: RevisionLabelString [0..1]</code></li>\n<li><code>pncVectorLength: PositiveInteger [0..1]</code></li>\n<li><code>pncVectorOffset: PositiveInteger [0..1]</code></li>\n<li><code>systemVersion: RevisionLabelString</code></li>\n<li><code>RootSwCompositionPrototype</code>: Spezialisiert <code>AtpPrototype</code> und <code>Identifiable</code>. Aggregiert von <code>System</code> (<code>+rootSoftwareComposition 0..1</code>, <code>«atpVariation,atpSplitable»</code>).</li>\n<li><code>CompositionSwComponentType</code>: Spezialisiert <code>SwComponentType</code>. Typisiert <code>RootSwCompositionPrototype</code> über <code>«isOfType»</code> (<code>+softwareComposition 1 {redefines atpType}</code>, Gegenseite <code>*</code>).</li>\n<li><code>FlatMap</code>: Spezialisiert <code>ARElement</code>, <code>AtpBlueprint</code>, <code>AtpBlueprintable</code>. Angebunden an <code>RootSwCompositionPrototype</code> über <code>+flatMap 0..1</code> (<code>«atpSplitable»</code>).</li>\n<li><code>SystemMapping</code>: Spezialisiert <code>Identifiable</code>. Aggregiert von <code>System</code> (<code>+mapping 0..*</code>, <code>«atpVariation,atpSplitable»</code>).</li>\n<li><code>FibexElement</code>: Spezialisiert <code>PackageableElement</code>. Referenziert von <code>System</code> (<code>+fibexElement *</code>, <code>«atpVariation»</code>).</li>\n<li><code>ClientIdDefinitionSet</code>: Spezialisiert <code>ARElement</code>. Aggregiert von <code>System</code> (<code>+clientIdDefinitionSet 0..*</code>).</li>\n<li><code>ClientIdDefinition</code>: Spezialisiert <code>Identifiable</code>, Attribut <code>clientId: Numerical</code>. Aggregiert von <code>ClientIdDefinitionSet</code> (<code>+clientIdDefinition 0..*</code>, <code>«atpVariation,atpSplitable»</code>).</li>\n<li><code>ClientServerOperation</code>: Spezialisiert <code>AtpStructureElement</code> und <code>Identifiable</code>. Attribut <code>+ diagArgIntegrity: Boolean [0..1]</code>. Referenziert von <code>ClientIdDefinition</code> über gerichtete Instanz-Referenz (<code>+clientServerOperation 1</code>, annotiert mit Stereotyp <code>«instanceRef»</code>).</li>\n<li><code>J1939SharedAddressCluster</code>: Spezialisiert <code>Identifiable</code>. Wird von <code>System</code> aggregiert (<code>+j1939SharedAddressCluster 0..*</code>, <code>«atpVariation,atpSplitable»</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Verhaltens- oder Sequenzdiagramm-Elemente. Die Beziehungen definieren die statische Strukturhierarchie zur Systemgenerierung und Software-Zusammenstellung.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Unterstützung für J1939-Netzwerke durch variable und splitbare Aggregation von <code>J1939SharedAddressCluster</code> (<code>0..*</code>) direkt am <code>System</code>. Die Instanz-Referenz <code>+clientServerOperation</code> von <code>ClientIdDefinition</code> auf <code>ClientServerOperation</code> ist explizit mit der Multiplizität <code>1</code> versehen. <code>ClientServerOperation</code> stellt das optionale Attribut <code>diagArgIntegrity</code> zur Absicherung von Diagnose-Argumenten bereit. Explizite Bindungszeit-Annotationen an den Variationspunkten im Diagramm sind entfallen.</p>"}, {"id": "FIG-f6abf0d0fa45df67", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Metamodell-Struktur des AUTOSAR-System-Templates. Dargestellt ist die Integration der Root-Software-Komposition in <code>System</code>, ergänzt um Software-Cluster (<code>CpSoftwareCluster</code>), Interpolations-Routine-Mappings (<code>InterpolationRoutineMappingSet</code>), FlatMap, variable System-Mappings, FibexElement-Referenzen, Client-ID-Definitionen sowie J1939-Shared-Address-Cluster.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Klassendiagramm spezifiziert folgende Entitäten, Attribute und Assoziationen:</p>\n<ul class=\"fig-list\">\n<li><code>System</code>: Spezialisiert <code>ARElement</code> und <code>AtpStructureElement</code>. Attribute:</li>\n<li><code>containerIPduHeaderByteOrder: ByteOrderEnum [0..1]</code></li>\n<li><code>ecuExtractVersion: RevisionLabelString [0..1]</code></li>\n<li><code>pncVectorLength: PositiveInteger [0..1]</code></li>\n<li><code>pncVectorOffset: PositiveInteger [0..1]</code></li>\n<li><code>systemVersion: RevisionLabelString</code></li>\n<li><code>RootSwCompositionPrototype</code>: Spezialisiert <code>AtpPrototype</code> und <code>Identifiable</code>. Aggregiert von <code>System</code> (<code>+rootSoftwareComposition 0..1</code>, <code>«atpVariation,atpSplitable»</code>).</li>\n<li><code>CompositionSwComponentType</code>: Spezialisiert <code>SwComponentType</code>. Typisiert <code>RootSwCompositionPrototype</code> über <code>«isOfType»</code> (<code>+softwareComposition 1 {redefines atpType}</code>, Gegenseite <code><em></code>). Aggregiert <code>SwComponentPrototype</code> (<code>+component 0..</em></code>, <code>«atpVariation,atpSplitable»</code>).</li>\n<li><code>SwComponentPrototype</code>: Spezialisiert <code>AtpPrototype</code>. Aggregiert in <code>CompositionSwComponentType</code>.</li>\n<li><code>CpSoftwareCluster</code>: Spezialisiert <code>ARElement</code>. Aggregiert von <code>System</code> (<code>+swCluster 0..<em></code>, <code>«atpSplitable,atpVariation»</code>). Referenziert <code>CompositionSwComponentType</code> (<code>+swComposition 0..</em></code>, <code>«atpVariation,atpSplitable»</code>) sowie <code>SwComponentPrototype</code> (<code>+component 0..*</code>, <code>«atpVariation,atpSplitable»</code>).</li>\n<li><code>InterpolationRoutineMappingSet</code>: Spezialisiert <code>ARElement</code>. Aggregiert von <code>System</code> (<code>+interpolationRoutineMappingSet 0..*</code>).</li>\n<li><code>FlatMap</code>: Spezialisiert <code>ARElement</code>, <code>AtpBlueprint</code>, <code>AtpBlueprintable</code>. Angebunden an <code>RootSwCompositionPrototype</code> über <code>+flatMap 0..1</code> (<code>«atpSplitable»</code>).</li>\n<li><code>SystemMapping</code>: Spezialisiert <code>Identifiable</code>. Aggregiert von <code>System</code> (<code>+mapping 0..*</code>, <code>«atpVariation,atpSplitable»</code>).</li>\n<li><code>FibexElement</code>: Spezialisiert <code>PackageableElement</code>. Referenziert von <code>System</code> (<code>+fibexElement *</code>, <code>«atpVariation»</code>).</li>\n<li><code>ClientIdDefinitionSet</code>: Spezialisiert <code>ARElement</code>. Aggregiert von <code>System</code> (<code>+clientIdDefinitionSet 0..*</code>).</li>\n<li><code>ClientIdDefinition</code>: Spezialisiert <code>Identifiable</code>, Attribut <code>clientId: Numerical</code>. Aggregiert von <code>ClientIdDefinitionSet</code> (<code>+clientIdDefinition 0..*</code>, <code>«atpVariation,atpSplitable»</code>).</li>\n<li><code>ClientServerOperation</code>: Spezialisiert <code>AtpStructureElement</code> und <code>Identifiable</code>. Attribut <code>+ diagArgIntegrity: Boolean [0..1]</code>. Referenziert von <code>ClientIdDefinition</code> über gerichtete Instanz-Referenz (<code>+clientServerOperation 1</code>, annotiert mit Stereotyp <code>«instanceRef»</code>).</li>\n<li><code>J1939SharedAddressCluster</code>: Spezialisiert <code>Identifiable</code>. Wird von <code>System</code> aggregiert (<code>+j1939SharedAddressCluster 0..*</code>, <code>«atpVariation,atpSplitable»</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Verhaltens- oder Sequenzdiagramm-Elemente. Die Beziehungen definieren die statische Strukturhierarchie zur Systemgenerierung und Software-Zusammenstellung.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Unterstützung für Software-Clusterung über die Aggregation von <code>CpSoftwareCluster</code> (<code>0..*</code>) am <code>System</code> mit Verknüpfungen zu <code>CompositionSwComponentType</code> und <code>SwComponentPrototype</code>. Zudem wird <code>InterpolationRoutineMappingSet</code> als Aggregation am <code>System</code> bereitgestellt. Weiterhin Unterstützung für J1939-Netzwerke über <code>J1939SharedAddressCluster</code>. Die Instanz-Referenz <code>+clientServerOperation</code> von <code>ClientIdDefinition</code> auf <code>ClientServerOperation</code> besitzt Multiplizität <code>1</code>. <code>ClientServerOperation</code> enthält das Attribut <code>diagArgIntegrity</code>. Explizite Bindungszeit-Annotationen an den Variationspunkten im Diagramm sind entfallen.</p>"}], "trans": [{"from": "FIG-0c3d3227a0ac6869", "to": "FIG-8b7486956206a43a", "fr": "R3.0.7", "tr": "R3.1.5", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-8b7486956206a43a", "to": "FIG-fbdcd4249609ea38", "fr": "R3.1.5", "tr": "R3.2.3", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>System: Neue Attribute <code>pncVectorLength: Integer [0..1]</code> und <code>pncVectorOffset: Integer [0..1]</code> hinzugefügt.</li>\n<li>System -> SoftwareComposition (<code>+softwareComposition</code>): Multiplizität von <code>1</code> auf <code>0..1</code> gelockert.</li>\n<li>System -> SystemMapping (<code>+mapping</code>): Multiplizität von <code>1</code> auf <code>0..1</code> gelockert.</li>\n</ul>"}, {"from": "FIG-fbdcd4249609ea38", "to": "FIG-a65899894acfeb62", "fr": "R3.2.3", "tr": "R4.0.3", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>System: Datentypen der Attribute geändert; <code>ecuExtractVersion</code> und <code>systemVersion</code> von <code>String</code> zu <code>RevisionLabelString</code>, <code>pncVectorLength</code> und <code>pncVectorOffset</code> von <code>Integer</code> zu <code>PositiveInteger</code>. Spezialisierung um <code>AtpStructureElement</code> ergänzt.</li>\n<li>SoftwareComposition: Umbenannt zu <code>RootSwCompositionPrototype</code> (stereotypisiert als <code>AtpPrototype</code>, spezialisiert <code>Identifiable</code>). Aggregationsrolle von <code>+softwareComposition</code> zu <code>+rootSoftwareComposition</code> geändert mit Stereotyp <code>«atpVariation»</code> und Tag <code>Vh.latestBindingTime = SystemDesignTime</code>.</li>\n<li>SwComponentType / CompositionSwComponentType: <code>ComponentType</code> und <code>Composition::CompositionType</code> ersetzt durch <code>SwComponentType</code> und <code>Composition::CompositionSwComponentType</code>. Typisierungsassoziation <code>«isOfType»</code> am Zielende mit <code>{redefines atpType}</code> annotiert.</li>\n<li>FlatMap: Neue Klasse <code>FlatMap::FlatMap</code> (spezialisiert <code>ARElement</code>, <code>AtpBlueprint</code>, <code>AtpBlueprintable</code>) über Assoziation <code>+flatMap 0..1</code> von <code>RootSwCompositionPrototype</code> angebunden.</li>\n<li>System -> SystemMapping (<code>+mapping</code>): Multiplizität von <code>0..1</code> auf <code>0..*</code> erweitert; Stereotyp <code>«atpVariation,atpSplitable»</code> mit Tag <code>Vh.latestBindingTime = PostBuild</code> ergänzt.</li>\n<li>System -> FibexCore::FibexElement (<code>+fibexElement</code>): Stereotyp <code>«atpVariation»</code> mit Tag <code>Vh.latestBindingTime = PostBuild</code> ergänzt.</li>\n</ul>"}, {"from": "FIG-a65899894acfeb62", "to": "FIG-47c6d78759dd8d22", "fr": "R4.0.3", "tr": "R4.1.3", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>CompositionSwComponentType: Paketpräfix entfernt (<code>Composition::CompositionSwComponentType</code> zu <code>CompositionSwComponentType</code>).</li>\n<li>FibexElement: Paketpräfix entfernt (<code>FibexCore::FibexElement</code> zu <code>FibexElement</code>).</li>\n<li>FlatMap: Paketpräfix entfernt (<code>FlatMap::FlatMap</code> zu <code>FlatMap</code>).</li>\n<li>RootSwCompositionPrototype -> FlatMap: Assoziationsende mit Stereotyp <code>«atpSplitable»</code> annotiert.</li>\n<li>Variations-Tags: Schreibweise der Tag-Schlüssel und -Werte von PascalCase auf camelCase vereinheitlicht (<code>vh.latestBindingTime = systemDesignTime</code> bzw. <code>postBuild</code>).</li>\n</ul>"}, {"from": "FIG-47c6d78759dd8d22", "to": "FIG-b4e7ad31f601609c", "fr": "R4.1.3", "tr": "R4.2.2", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>System: Neues Attribut <code>containerIPduHeaderByteOrder: ByteOrderEnum [0..1]</code> hinzugefügt.</li>\n<li>System -> RootSwCompositionPrototype (<code>+rootSoftwareComposition</code>): Stereotyp von <code>«atpVariation»</code> auf <code>«atpVariation,atpSplitable»</code> erweitert.</li>\n<li>ClientIdDefinitionSet: Neue Klasse (spezialisiert <code>ARElement</code>), aggregiert durch <code>System</code> über <code>+clientIdDefinitionSet 0..*</code>.</li>\n<li>ClientIdDefinition: Neue Klasse (spezialisiert <code>Identifiable</code>, Attribut <code>clientId: Numerical</code>), aggregiert durch <code>ClientIdDefinitionSet</code> über <code>+clientIdDefinition 0..*</code> mit Stereotyp <code>«atpVariation,atpSplitable»</code>.</li>\n<li>ClientServerOperation: Neue Klasse (spezialisiert <code>AtpStructureElement</code>, <code>Identifiable</code>), referenziert von <code>ClientIdDefinition</code> über gerichtete Assoziation <code>+clientServerOperation</code> mit Stereotyp <code>«instanceRef»</code>.</li>\n</ul>"}, {"from": "FIG-b4e7ad31f601609c", "to": "FIG-189e6e57e744ad1c", "fr": "R4.2.2", "tr": "R4.3.1", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>J1939SharedAddressCluster: Neue Klasse (spezialisiert <code>Identifiable</code>), aggregiert von <code>System</code> über Komposition <code>+j1939SharedAddressCluster 0..*</code> mit Stereotyp <code>«atpVariation,atpSplitable»</code>.</li>\n<li>ClientIdDefinition -> ClientServerOperation (<code>+clientServerOperation</code>): Multiplizität <code>1</code> explizit ergänzt; Stereotyp <code>«instanceRef»</code> als Textmarkierung an der Beziehungslinie platziert.</li>\n<li>Variations-Notizen: Spezifische Notizboxen zu Bindungszeiten (<code>vh.latestBindingTime</code>) an den Variationspunkten entfernt.</li>\n</ul>"}, {"from": "FIG-189e6e57e744ad1c", "to": "FIG-ef04d044cbe0688d", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li><code>System</code>: Leerzeichen vor dem Doppelpunkt in Attributdeklarationen vereinheitlicht (z. B. <code>:ByteOrderEnum</code> zu <code>: ByteOrderEnum</code>).</li>\n<li><code>ClientIdDefinition</code>: Bereinigung von überlappendem Text zwischen dem Klassennamen und der Assoziationsbeschriftung <code>+clientServerOperation</code>.</li>\n<li><code>RootSwCompositionPrototype</code>: Die Multiplizität <code>*</code> am Assoziationsende zu <code>CompositionSwComponentType</code> ist optisch deutlicher platziert.</li>\n</ul>"}, {"from": "FIG-ef04d044cbe0688d", "to": "FIG-e77496564191b9f7", "fr": "R18-10_R4.4.0_R1.5.0", "tr": "R19-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><code>ClientServerOperation</code>: Neues optionales Attribut <code>+ diagArgIntegrity: Boolean [0..1]</code> hinzugefügt.</li>\n</ul>"}, {"from": "FIG-e77496564191b9f7", "to": "FIG-f6abf0d0fa45df67", "fr": "R19-11", "tr": "R20-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><code>CpSoftwareCluster</code>: Neue Klasse (<code>ARElement</code>), aggregiert von <code>System</code> (<code>+swCluster 0..<em></code>, <code>«atpSplitable,atpVariation»</code>), mit Assoziationen zu <code>CompositionSwComponentType</code> (<code>+swComposition 0..</em></code>, <code>«atpVariation,atpSplitable»</code>) und <code>SwComponentPrototype</code> (<code>+component 0..*</code>, <code>«atpVariation,atpSplitable»</code>).</li>\n<li><code>SwComponentPrototype</code>: Neue Klasse (<code>AtpPrototype</code>), aggregiert von <code>CompositionSwComponentType</code> (<code>+component 0..*</code>, <code>«atpVariation,atpSplitable»</code>).</li>\n<li><code>InterpolationRoutineMappingSet</code>: Neue Klasse (<code>ARElement</code>), aggregiert von <code>System</code> (<code>+interpolationRoutineMappingSet 0..*</code>).</li>\n</ul>"}]};
